	dp := make([][]int64, n)
	for i := range dp {
		dp[i] = make([]int64, n)
		for j := range dp[i] {
			dp[i][j] = INF
		}
	}

	// Base case: no triangulation needed for a single edge (i == j) or two vertices (i+1 == j)
	// For a triangle (j == i+2), dp[i][i+2] = (i+1)*(i+2)*(i+3) in 1-indexed
	// In 0-indexed: vertices i, i+1, i+2 -> labels (i+1), (i+2), (i+3)
	// So weight = (i+1)*(i+2)*(i+3)

