			j := i + length - 1
			// Try all possible k such that we form triangle (i, k, j)
			// k ranges from i+1 to j-1
			minVal := INF
			for k := i + 1; k < j; k++ {
				// The triangle is (i, k, j) with labels (i+1), (k+1), (j+1)
